    /// The token name in `tokens.json`, e.g. `"border-subtle-01"`.
    pub const fn name(self) -> &'static str {
        COLOR_NAMES[self as usize]
    }
    /// The token's usage note from `tokens.json`.
    pub const fn usage(self) -> &'static str {
        COLOR_USAGE[self as usize]
    }
    /// Look a role up by its token name.
    pub fn from_name(name: &str) -> Option<Self> {
        COLOR_NAMES.iter().position(|n| *n == name).map(|i| Self::ALL[i])
    }
