/// Every Carbon type style in `tokens.json`; see [`TypeStyle::spec`].
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum TypeStyle {
    /// `label-01` (Productive): Field labels, tag text, breadcrumb.
    Label01,
    /// `label-02` (Productive): Larger labels.
    Label02,
    /// `helper-text-01` (Productive): Helper/error text under fields.
    HelperText01,
    /// `helper-text-02` (Productive): Larger helper text.
    HelperText02,
    /// `legal-01` (Productive): Legal fine print.
    Legal01,
    /// `legal-02` (Productive): Larger legal text.
    Legal02,
    /// `body-compact-01` (Productive): Default UI text: buttons, inputs, cells, menu items.
    BodyCompact01,
    /// `body-compact-02` (Productive): Large controls.
    BodyCompact02,
    /// `body-01` (Productive): Paragraphs in product UI.
    Body01,
    /// `body-02` (Productive): Long-form reading.
    Body02,
    /// `heading-compact-01` (Productive): Notification titles, dense headings.
    HeadingCompact01,
    /// `heading-compact-02` (Productive): Panel titles.
    HeadingCompact02,
    /// `heading-01` (Productive): Small headings with body-01.
    Heading01,
    /// `heading-02` (Productive): Small headings with body-02.
    Heading02,
    /// `heading-03` (Productive): Modal and card titles.
    Heading03,
    /// `heading-04` (Productive): Page titles in product UI.
    Heading04,
    /// `heading-05` (Productive): Large page titles.
    Heading05,
    /// `heading-06` (Productive): Display headings.
    Heading06,
    /// `heading-07` (Productive): Large display.
    Heading07,
    /// `code-01` (Code): Inline code, IDs.
    Code01,
    /// `code-02` (Code): Code blocks.
    Code02,
    /// `body-compact-cjk-01` (CJK): Chinese/Japanese UI text: 14/22. CJK needs ~1.6 line height and no positive tracking.
    BodyCompactCjk01,
    /// `body-cjk-01` (CJK): CJK paragraphs in messages: 14/24.
    BodyCjk01,
    /// `label-cjk-01` (CJK): CJK labels and helper text: 12/18.
    LabelCjk01,
    /// `heading-cjk-03` (CJK): CJK titles: 20/30, semibold (CJK light weights are too thin).
    HeadingCjk03,
}

